// The Worker entry (wrangler.jsonc "main"): OpenNext's generated worker, wrapped so the store can
// give back per-request resources -- lib/prisma.ts's database clients -- once a request has
// completely finished: its response body fully sent (pages stream) and every waitUntil() task
// (after(), background emails and webhooks) settled. Code registers what to run then under
// Symbol.for('yallahaul.requestEndHooks'), keyed by the request's ExecutionContext.
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js'
// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js'
// The live chat relay (lib/live-chat/hub.ts), a Durable Object bound as LIVE_CHAT in wrangler.jsonc.
export { LiveChatHub } from './lib/live-chat/hub'
import { verifyTicket } from './lib/live-chat/ticket'

import { ORDER_WATCH_CRON, ORDER_WATCH_KEY, inQuietHours, parseWatch, reconcileDue } from './lib/order-watch'
import { HOURLY_JOBS_KEY, hourlyJobsDue, parseHourlyJobs } from './lib/hourly-jobs'
import { SERVER_ERRORS_KEY, countsAsServerError, noteServerError, parseServerErrors } from './lib/server-errors'

type ExecutionContext = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void }

const REQUEST_END_HOOKS = Symbol.for('yallahaul.requestEndHooks')
const hooks: WeakMap<object, Array<() => unknown>> = ((globalThis as any)[REQUEST_END_HOOKS] ??= new WeakMap())
// Requests this isolate has started and completely finished (read by /api/internal/runtime-stats):
// a gap that keeps growing means requests whose work never ends, holding their memory.
const requestCounts: { started: number; finished: number } = ((globalThis as any)[Symbol.for('yallahaul.requestCounts')] ??= { started: 0, finished: 0 })

// The key the daily cron's request to /api/internal/daily carries (lib/internal-job.ts): random,
// made once per Worker instance and only ever in its memory.
const INTERNAL_JOB_KEY = Symbol.for('yallahaul.internalJobKey')
const internalJobKey = (): string => ((globalThis as any)[INTERNAL_JOB_KEY] ??= `${crypto.randomUUID()}${crypto.randomUUID()}`)

// A scheduled job that answered with an error: app/api/internal/job-failed keeps it in the activity log and tells
// the owner (lib/order-alerts.ts). Failing to report it only loses the alert; the cron run still records the error.
async function reportJobFailure(site: string, path: string, status: number, detail: string, env: any, ctx: ExecutionContext) {
  try {
    const request = new Request(`${site}/api/internal/job-failed`, { method: 'POST', headers: { 'x-internal-job': internalJobKey(), 'content-type': 'application/json' }, body: JSON.stringify({ path, status, detail: detail.slice(0, 300) }) })
    await (await worker.fetch(request, env, ctx)).text()
  } catch (error) {
    console.error('[cron] job failure not reported', path, error)
  }
}

// A server error the store answered with (lib/server-errors.ts): counted in the media bucket, which works even
// when the database is what fails. Once there are enough in the window, the store is asked to tell the owner
// (app/api/internal/server-errors); only a try that worked counts as told. Losing a count only loses the alert.
async function recordServerError(origin: string, path: string, status: number, env: any, ctx: ExecutionContext) {
  try {
    const bucket = env?.MEDIA_BUCKET
    if (!bucket) return
    const now = Date.now()
    const object = await bucket.get(SERVER_ERRORS_KEY)
    const { state, alert } = noteServerError(object ? parseServerErrors(await object.text()) : null, now, path, status)
    await bucket.put(SERVER_ERRORS_KEY, JSON.stringify(state))
    if (!alert) return
    const request = new Request(`${origin}/api/internal/server-errors`, { method: 'POST', headers: { 'x-internal-job': internalJobKey(), 'content-type': 'application/json' }, body: JSON.stringify({ state }) })
    const response = await worker.fetch(request, env, ctx)
    await response.text().catch(() => '')
    if (response.ok) await bucket.put(SERVER_ERRORS_KEY, JSON.stringify({ ...state, alertedAt: now }))
  } catch (error) {
    console.error('[server-errors] not recorded', error)
  }
}

// A live chat connection (components/assistant-widget.tsx, Admin › Live chat): only with a signed ticket
// from the store's own routes (lib/live-chat/ticket.ts) and from this site's pages; then handed to the
// relay. It never reaches Next.js, which can't hold a socket open.
async function liveChatSocket(request: Request, env: any): Promise<Response> {
  if (request.headers.get('Upgrade') !== 'websocket') return new Response('Expected a WebSocket', { status: 426 })
  const url = new URL(request.url)
  const origin = request.headers.get('Origin')
  if (origin) {
    try { if (new URL(origin).host !== url.host) return new Response('Forbidden', { status: 403 }) } catch { return new Response('Forbidden', { status: 403 }) }
  }
  const ticket = await verifyTicket(String(env?.AUTH_SECRET || ''), url.searchParams.get('ticket'))
  if (!ticket) return new Response('Forbidden', { status: 403 })
  const namespace = env?.LIVE_CHAT
  if (!namespace) return new Response('Live chat is not available', { status: 503 })
  const headers = new Headers(request.headers)
  headers.set('x-live-role', ticket.role)
  headers.set('x-live-conversation', ticket.conversationId || '')
  return namespace.get(namespace.idFromName('hub')).fetch(new Request('https://live-chat/socket', { headers }))
}

const worker = {
  async fetch(request: Request, env: unknown, ctx: ExecutionContext): Promise<Response> {
    if (new URL(request.url).pathname === '/api/live-chat/socket') return liveChatSocket(request, env)
    requestCounts.started++
    const pending: Promise<unknown>[] = []
    // The context OpenNext and the app see: the same, except that waitUntil() tasks are tracked.
    const requestCtx: ExecutionContext = new Proxy(ctx, {
      get(target, prop) {
        if (prop === 'waitUntil') return (promise: Promise<unknown>) => { pending.push(promise); target.waitUntil(promise) }
        const value = Reflect.get(target, prop, target)
        return typeof value === 'function' ? value.bind(target) : value
      },
    })
    const finish = async () => {
      // Tasks can start more tasks, so wait until none are left.
      while (pending.length) await Promise.allSettled(pending.splice(0))
      const requestHooks = hooks.get(requestCtx) ?? []
      hooks.delete(requestCtx)
      await Promise.allSettled(requestHooks.map(hook => Promise.resolve().then(hook)))
      requestCounts.finished++
    }

    const noteStatus = (status: number) => {
      const url = new URL(request.url)
      if (countsAsServerError(status, url.pathname, request.headers.has('x-internal-job'))) ctx.waitUntil(recordServerError(url.origin, url.pathname, status, env, ctx))
    }
    let response: Response
    try {
      response = await handler.fetch(request, env, requestCtx)
    } catch (error) {
      noteStatus(500)
      ctx.waitUntil(finish())
      throw error
    }
    noteStatus(response.status)
    if (response.body) {
      // Pages stream: database queries can still run while the body is being sent.
      const { readable, writable } = new TransformStream()
      pending.push(response.body.pipeTo(writable).catch(() => undefined))
      response = new Response(readable, response)
    }
    ctx.waitUntil(finish())
    return response
  },

  // The cron triggers (wrangler.jsonc "triggers"). Daily: the owner's morning summary and the
  // review-request emails. Every 15 minutes: the order watch (lib/order-watch.ts). Both go through
  // fetch() like any request, so the app code, its settings and secrets are the same; the request
  // never leaves this Worker.
  async scheduled(controller: { cron: string; scheduledTime: number }, env: any, ctx: ExecutionContext): Promise<void> {
    const site = String(env?.NEXT_PUBLIC_SITE_URL || env?.APP_URL || 'https://internal.invalid').replace(/\/$/, '')
    const paths: string[] = []
    if (controller.cron === ORDER_WATCH_CRON) {
      // Once an hour, while there is work for them (lib/hourly-jobs.ts), and every 6 hours regardless: refunds the store
      // has not recorded are confirmed with the gateway (lib/refund-reconciliation.ts), card checkouts left at the
      // payment page for over 30 minutes give their stock back (app/api/internal/release-expired-reservations), and
      // failed messages are tried again (lib/outbox.ts). Each run wakes the database, so they never run on the other
      // quarter-hours, and an hour with nothing to do costs only a read of the marker in the media bucket. The idle
      // check runs last and clears the marker when nothing is left.
      let hourly = false
      if (reconcileDue(controller.scheduledTime)) {
        let marker = null
        try {
          const object = await env?.MEDIA_BUCKET?.get(HOURLY_JOBS_KEY)
          marker = object ? parseHourlyJobs(await object.text()) : null
        } catch { /* unreadable: the jobs run */ }
        hourly = hourlyJobsDue(controller.scheduledTime, marker)
      }
      if (hourly) paths.push('/api/internal/reconcile-refunds')
      if (hourly) paths.push('/api/internal/release-expired-reservations')
      if (hourly) paths.push('/api/internal/retry-outbox')
      if (hourly) paths.push('/api/internal/hourly-idle')
      // The marker file is the only thing read first: no order being watched, or night time, means the
      // database is never touched by the order watch.
      try {
        const object = await env?.MEDIA_BUCKET?.get(ORDER_WATCH_KEY)
        const watch = object ? parseWatch(await object.text()) : null
        if (watch?.armed && !inQuietHours(new Date(controller.scheduledTime), watch.tz)) paths.push('/api/internal/order-watch')
      } catch { /* the order watch waits for the next run */ }
    } else {
      paths.push('/api/internal/daily')
    }
    // Each job runs even when an earlier one failed. The first failure is reported to the cron run, and every
    // failure is told to the owner (at most once per job every 6 hours).
    let failure: Error | null = null
    for (const path of paths) {
      const request = new Request(`${site}${path}`, { method: 'POST', headers: { 'x-internal-job': internalJobKey(), 'x-cron': controller.cron } })
      const response = await worker.fetch(request, env, ctx)
      const body = await response.text().catch(() => '')
      if (response.ok) continue
      if (!failure) failure = new Error(`${path} answered ${response.status}: ${body.slice(0, 300)}`)
      await reportJobFailure(site, path, response.status, body, env, ctx)
    }
    if (failure) throw failure
  },
}

export default worker
